// Audio-driven waits. The manifest is the source of truth for every voiceover
// duration; visual timelines wait on it instead of hand-tuned numbers.
//
// Generated by scripts/generate-tts.py. Kept under data/ so Vite can
// import it statically.

import { Audio, View2D } from "@revideo/2d";
import { all, waitFor, ThreadGenerator } from "@revideo/core";
import audioManifest from "../../data/audio-manifest.json";

type ManifestEntry = { durationSec: number; mediaFile?: string };
type Manifest = Record<string, ManifestEntry>;

const MANIFEST = audioManifest as Manifest;

/** Real duration of the generated voiceover MP3, in seconds. */
export function audioSec(audioId: string): number {
  const entry = MANIFEST[audioId];
  if (!entry) {
    console.warn(`audioSec: no manifest entry for "${audioId}"`);
    return 1.0;
  }
  return entry.durationSec;
}

/** Public URL of the generated MP3 (served from public/audio/). */
export function audioUrl(audioId: string): string {
  const entry = MANIFEST[audioId];
  const file = entry?.mediaFile ?? `${audioId}.mp3`;
  return `/audio/${file}`;
}

/**
 * Play `audioId` while running `visuals` in parallel, then hold for `pad`
 * seconds of silence so the beat doesn't cut off the voiceover tail.
 *
 * Use this as the only sync primitive: every micro-beat becomes one call.
 *
 *   yield* playAndWait(view, "ch2-briefings", function*() {
 *     yield* tree().highlightPath("artifacts/briefings", 0.3);
 *   });
 */
export function* playAndWait(
  view: View2D,
  audioId: string,
  visuals?: () => ThreadGenerator,
  pad = 0.35,
): ThreadGenerator {
  view.add(<Audio src={audioUrl(audioId)} play={true} time={0} />);
  const dur = audioSec(audioId);
  if (visuals) {
    yield* all(visuals(), waitFor(dur + pad));
  } else {
    yield* waitFor(dur + pad);
  }
}
